// atlas-0 review fix round 1, F3 seeded fault: a stub worker (wired the same way maplibre-gl's real
// worker is, `?worker&url`) padded with deterministic, gzip-incompressible bytes (a SHA-256 hash
// chain, not crypto.randomBytes, so this fixture reproduces identically on every checkout) so its
// gzip size exceeds RUNTIME_WORKER_BUDGET_BYTES (150 KB) on its own. PAD is passed into postMessage,
// not just its .length, so a minifier cannot constant-fold it away and shrink the file back under
// budget.
const PAD =
  "";
self.onmessage = (ev) => {
  postMessage({ pad: PAD, echo: ev.data });
};
export {};
